#include <iostream>
#include <vector>

using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    if (!(cin >> n)) return 0;

    vector<int> a(n);
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
    }

    int max_seen = 0;
    int hidden_count = 0;

    for (int i = n - 1; i >= 0; --i) {
        if (a[i] <= max_seen) {
            hidden_count++;
        } else {
            max_seen = a[i];
        }
    }

    cout << hidden_count << "\n";

    return 0;
}
